   128→/// https://github.com/ethereum/consensus-specs/blob/v1.1.9/specs/bellatrix/beacon-chain.md#notify_new_payload
   129→async fn notify_new_payload<T: BeaconChainTypes>(
   130→    chain: &Arc<BeaconChain<T>>,
   131→    block: BeaconBlockRef<'_, T::EthSpec>,
   132→) -> Result<PayloadVerificationStatus, BlockError> {
