   139→    let new_payload_response = execution_layer.notify_new_payload(block.try_into()?).await;
   140→
   141→    match new_payload_response {
   142→        Ok(status) => match status {
   143→            PayloadStatus::Valid => Ok(PayloadVerificationStatus::Verified),
   144→            PayloadStatus::Syncing | PayloadStatus::Accepted => {
   145→                Ok(PayloadVerificationStatus::Optimistic)
   146→            }
