   410→/// Calls `partially_verify_execution_payload` and then updates the payload header in the `state`.
   411→///
   412→/// ## Specification
   413→///
   414→/// Partially equivalent to the `process_execution_payload` function:
   415→///
   416→/// https://github.com/ethereum/consensus-specs/blob/v1.1.5/specs/merge/beacon-chain.md#process_execution_payload
   417→pub fn process_execution_payload<E: EthSpec, Payload: AbstractExecPayload<E>>(
   418→    state: &mut BeaconState<E>,
   419→    body: BeaconBlockBodyRef<E, Payload>,
   420→    spec: &ChainSpec,
   421→) -> Result<(), BlockProcessingError> {
   422→    partially_verify_execution_payload::<E, Payload>(state, state.slot(), body, spec)?;
   423→    let payload = body.execution_payload()?;
   424→    match state.latest_execution_payload_header_mut()? {
   425→        ExecutionPayloadHeaderRefMut::Bellatrix(header_mut) => {
   426→            match payload.to_execution_payload_header() {
   427→                ExecutionPayloadHeader::Bellatrix(header) => *header_mut = header,
   428→                _ => return Err(BlockProcessingError::IncorrectStateType),
   429→            }
   430→        }
   431→        ExecutionPayloadHeaderRefMut::Capella(header_mut) => {
   432→            match payload.to_execution_payload_header() {
   433→                ExecutionPayloadHeader::Capella(header) => *header_mut = header,
   434→                _ => return Err(BlockProcessingError::IncorrectStateType),
   435→            }
   436→        }
   437→        ExecutionPayloadHeaderRefMut::Deneb(header_mut) => {
   438→            match payload.to_execution_payload_header() {
   439→                ExecutionPayloadHeader::Deneb(header) => *header_mut = header,
   440→                _ => return Err(BlockProcessingError::IncorrectStateType),
   441→            }
   442→        }
   443→        ExecutionPayloadHeaderRefMut::Electra(header_mut) => {
   444→            match payload.to_execution_payload_header() {
   445→                ExecutionPayloadHeader::Electra(header) => *header_mut = header,
   446→                _ => return Err(BlockProcessingError::IncorrectStateType),
   447→            }
   448→        }
   449→        ExecutionPayloadHeaderRefMut::Fulu(header_mut) => {
   450→            match payload.to_execution_payload_header() {
   451→                ExecutionPayloadHeader::Fulu(header) => *header_mut = header,
   452→                _ => return Err(BlockProcessingError::IncorrectStateType),
   453→            }
   454→        }
   455→        ExecutionPayloadHeaderRefMut::Gloas(header_mut) => {
   456→            match payload.to_execution_payload_header() {
   457→                ExecutionPayloadHeader::Gloas(header) => *header_mut = header,
   458→                _ => return Err(BlockProcessingError::IncorrectStateType),
   459→            }
   460→        }
   461→    }
   462→
   463→    Ok(())
   464→}
