   466→/// These functions will definitely be called before the merge. Their entire purpose is to check if
   467→/// the merge has happened or if we're on the transition block. Thus we don't want to propagate
   468→/// errors from the `BeaconState` being an earlier variant than `BeaconStateBellatrix` as we'd have to
   469→/// repeatedly write code to treat these errors as false.
   470→/// https://github.com/ethereum/consensus-specs/blob/dev/specs/bellatrix/beacon-chain.md#is_merge_transition_complete
   471→pub fn is_merge_transition_complete<E: EthSpec>(state: &BeaconState<E>) -> bool {
   472→    if state.fork_name_unchecked().capella_enabled() {
   473→        true
   474→    } else if state.fork_name_unchecked().bellatrix_enabled() {
   475→        // We must check defaultness against the payload header with 0x0 roots, as that's what's meant
   476→        // by `ExecutionPayloadHeader()` in the spec.
   477→        state
   478→            .latest_execution_payload_header()
   479→            .map(|header| !header.is_default_with_zero_roots())
   480→            .unwrap_or(false)
   481→    } else {
   482→        false
   483→    }
   484→}
   485→/// https://github.com/ethereum/consensus-specs/blob/dev/specs/bellatrix/beacon-chain.md#is_merge_transition_block
   486→pub fn is_merge_transition_block<E: EthSpec, Payload: AbstractExecPayload<E>>(
   487→    state: &BeaconState<E>,
   488→    body: BeaconBlockBodyRef<E, Payload>,
   489→) -> bool {
   490→    // For execution payloads in blocks (which may be headers) we must check defaultness against
   491→    // the payload with `transactions_root` equal to the tree hash of the empty list.
   492→    body.execution_payload()
   493→        .map(|payload| {
   494→            !is_merge_transition_complete(state) && !payload.is_default_with_empty_roots()
   495→        })
   496→        .unwrap_or(false)
   497→}
   498→/// https://github.com/ethereum/consensus-specs/blob/dev/specs/bellatrix/beacon-chain.md#is_execution_enabled
   499→pub fn is_execution_enabled<E: EthSpec, Payload: AbstractExecPayload<E>>(
   500→    state: &BeaconState<E>,
   501→    body: BeaconBlockBodyRef<E, Payload>,
   502→) -> bool {
   503→    is_merge_transition_block(state, body) || is_merge_transition_complete(state)
   504→}
   505→
   506→/// https://github.com/ethereum/consensus-specs/blob/dev/specs/bellatrix/beacon-chain.md#compute_timestamp_at_slot
   507→pub fn compute_timestamp_at_slot<E: EthSpec>(
   508→    state: &BeaconState<E>,
   509→    block_slot: Slot,
   510→    spec: &ChainSpec,
   511→) -> Result<u64, ArithError> {
   512→    let slots_since_genesis = block_slot.as_u64().safe_sub(spec.genesis_slot.as_u64())?;
   513→    slots_since_genesis
   514→        .safe_mul(spec.seconds_per_slot)
   515→        .and_then(|since_genesis| state.genesis_time().safe_add(since_genesis))
   516→}
