   112→    /// Performs the required verifications of the payload when the chain is optimistically syncing.
   113→    ///
   114→    /// ## Specification
   115→    ///
   116→    /// Performs the verifications in the `verify_and_notify_new_payload` function:
   117→    ///
   118→    /// https://github.com/ethereum/consensus-specs/blob/v1.4.0-beta.2/specs/deneb/beacon-chain.md#modified-verify_and_notify_new_payload
   119→    pub fn perform_optimistic_sync_verifications(&self) -> Result<(), Error> {
   120→        self.verify_payload_block_hash()?;
   121→        self.verify_versioned_hashes()?;
   122→
   123→        Ok(())
   124→    }
   125→
   126→    /// Verify the block hash is consistent locally within Lighthouse.
   127→    ///
   128→    /// ## Specification
   129→    ///
   130→    /// Equivalent to `is_valid_block_hash` in the spec:
   131→    /// https://github.com/ethereum/consensus-specs/blob/v1.4.0-beta.2/specs/deneb/beacon-chain.md#is_valid_block_hash
   132→    pub fn verify_payload_block_hash(&self) -> Result<(), Error> {
   133→        let payload = self.execution_payload_ref();
   134→        let parent_beacon_block_root = self.parent_beacon_block_root().ok().cloned();
   135→
   136→        let _timer = metrics::start_timer(&metrics::EXECUTION_LAYER_VERIFY_BLOCK_HASH);
   137→
   138→        // Check that no transactions in the payload are zero length
   139→        if payload.transactions().iter().any(|slice| slice.is_empty()) {
   140→            return Err(Error::ZeroLengthTransaction);
   141→        }
   142→
   143→        let (header_hash, rlp_transactions_root) = calculate_execution_block_hash(
   144→            payload,
   145→            parent_beacon_block_root,
   146→            self.execution_requests().ok().copied(),
   147→        );
   148→
   149→        if header_hash != self.block_hash() {
   150→            return Err(Error::BlockHashMismatch {
   151→                computed: header_hash,
   152→                payload: payload.block_hash(),
   153→                transactions_root: rlp_transactions_root,
   154→            });
   155→        }
   156→
   157→        Ok(())
   158→    }
   159→
   160→    /// Verify the versioned hashes computed by the blob transactions match the versioned hashes computed from the commitments.
   161→    ///
   162→    /// ## Specification
   163→    ///
   164→    /// Equivalent to `is_valid_versioned_hashes` in the spec:
   165→    /// https://github.com/ethereum/consensus-specs/blob/v1.4.0-beta.2/specs/deneb/beacon-chain.md#is_valid_versioned_hashes
   166→    pub fn verify_versioned_hashes(&self) -> Result<(), Error> {
   167→        if let Ok(versioned_hashes) = self.versioned_hashes() {
   168→            verify_versioned_hashes(self.execution_payload_ref(), versioned_hashes)
   169→                .map_err(Error::VerifyingVersionedHashes)?;
   170→        }
   171→        Ok(())
   172→    }
   173→}
