   364→        if let Some(updated_gas_limit) = updated.gas_limit
   365→            && self.gas_limit != Some(updated_gas_limit)
   366→        {
   367→            self.gas_limit = Some(updated_gas_limit);
   368→            changed = true;
   369→        }
