   372→        if self.update_epoch != updated.update_epoch {
   373→            self.update_epoch = updated.update_epoch;
   374→            changed = true;
   375→        }
   376→
   377→        // Update `preparation_data` if it differs
   378→        if self.preparation_data != updated.preparation_data {
   379→            self.preparation_data = updated.preparation_data;
   380→            changed = true;
   381→        }
   382→
   383→        changed
